#include <iostream>
#include <iomanip>
#include <array>
#include <string_view>

struct Card {
    std::string_view face;
    std::string_view suit;
};

class DeckOfCards {
public:
    static constexpr size_t numberOfCards = 52;
    static constexpr size_t faces = 13;
    static constexpr size_t suits = 4;

    DeckOfCards() {
        static constexpr std::array<std::string_view, suits> suitNames = {
            "Hearts", "Diamonds", "Clubs", "Spades"
        };
        static constexpr std::array<std::string_view, faces> faceNames = {
            "Ace", "Deuce", "Three", "Four", "Five", "Six", "Seven",
            "Eight", "Nine", "Ten", "Jack", "Queen", "King"
        };

        for (size_t i = 0; i < deck.size(); ++i) {
            deck[i].face = faceNames[i % faces];
            deck[i].suit = suitNames[i / faces];
        }
    }

    // Deterministic linear congruential generator for reproducible shuffle
    void shuffleDeterministic() {
        unsigned long seed = 42;
        for (size_t i = 0; i < deck.size(); ++i) {
            seed = (seed * 1103515245 + 12345) & 0x7fffffff;
            size_t j = seed % numberOfCards;
            Card temp = deck[i];
            deck[i] = deck[j];
            deck[j] = temp;
        }
    }

    void dealFirstFour() const {
        for (size_t i = 0; i < 4; ++i) {
            std::cout << std::right << std::setw(5) << deck[i].face << " of "
                      << std::left << std::setw(8) << deck[i].suit
                      << ((i + 1) % 2 ? '\t' : '\n');
        }
    }

private:
    std::array<Card, numberOfCards> deck{};
};

int main() {
    DeckOfCards deck;
    deck.shuffleDeterministic();
    deck.dealFirstFour();
    return 0;
}

#include <iostream>
#include <iomanip>
#include <cstdint>

void displayBits(uint32_t value) {
    constexpr unsigned totalBits = sizeof(uint32_t) * 8;
    constexpr uint32_t mask = 1u << (totalBits - 1);

    std::cout << std::setw(10) << value << " = ";

    for (unsigned i = 1; i <= totalBits; ++i) {
        std::cout << ((value & mask) ? '1' : '0');
        value <<= 1;
        if (i % 8 == 0 && i != totalBits) {
            std::cout << ' ';
        }
    }
    std::cout << '\n';
}

int main() {
    uint32_t sample1 = 65000;
    uint32_t sample2 = 29;

    displayBits(sample1);
    displayBits(sample2);
    return 0;
}
